WIDTHS = [4, 8, 16, 32, 64]
N_RANDOM: Int = 2000
SEED: Int = 64
#: integer addition in doubles is exact below 2^53, so widths up to this are checked against it
EXACT_WIDTH: Int = 48

#| A gate's output: its value and the time it settles, one unit after its later input.
def nand(a: Num, ta: Num, b: Num, tb: Num) {
    return 1.0 - a * b, max(ta, tb) + 1.0
}

#| Ripple-carry addition of bit arrays a and b (least significant first) by nine-NAND full adders: the sum bits, the carry out, the time the last signal settles, and the gates used.
def ripple(a: Arr, b: Arr) {
    n: Int = len(a)
    s = zeros(n + 1)
    c = 0.0
    tc = 0.0
    latest = 0.0
    for i to n {
        n1, t1 = nand(a[i], 0.0, b[i], 0.0)
        n2, t2 = nand(a[i], 0.0, n1, t1)
        n3, t3 = nand(b[i], 0.0, n1, t1)
        x, tx = nand(n2, t2, n3, t3)
        n5, t5 = nand(x, tx, c, tc)
        n6, t6 = nand(x, tx, n5, t5)
        n7, t7 = nand(c, tc, n5, t5)
        sm, ts = nand(n6, t6, n7, t7)
        c, tc = nand(n5, t5, n1, t1)
        s[i] = sm
        latest = max(latest, max(ts, tc))
    }
    s[n] = c
    return s, latest, 9 * n
}

#| Kogge-Stone carry-lookahead addition: generate and propagate per bit, a prefix tree of log2(n) levels, then the sum bits; same results as ripple.
def lookahead(a: Arr, b: Arr) {
    n: Int = len(a)
    g = a * b
    p = zeros(n)
    for i to n {
        p[i] = abs(a[i] - b[i])
    }
    tg = ones(n)
    tp = ones(n)
    gates: Int = 2 * n
    d: Int = 1
    while d < n {
        g2 = copy(g)
        p2 = copy(p)
        tg2 = copy(tg)
        tp2 = copy(tp)
        for i from d to n {
            #: G = G_i or (P_i and G_(i-d)): an AND then an OR; P = P_i and P_(i-d)
            t_and = max(tp[i], tg[i - d]) + 1.0
            g2[i] = max(g[i], p[i] * g[i - d])
            tg2[i] = max(tg[i], t_and) + 1.0
            p2[i] = p[i] * p[i - d]
            tp2[i] = max(tp[i], tp[i - d]) + 1.0
            gates = gates + 3
        }
        g = g2
        p = p2
        tg = tg2
        tp = tp2
        d = 2 * d
    }
    s = zeros(n + 1)
    latest = 0.0
    for i to n {
        #: the carry into bit i is G over bits 0 .. i-1; the sum is the bit's own propagate XOR that carry
        own = abs(a[i] - b[i])
        if i == 0 {
            s[i] = own
            latest = max(latest, 1.0)
        }
        else {
            s[i] = abs(own - g[i - 1])
            latest = max(latest, max(1.0, tg[i - 1]) + 1.0)
        }
    }
    s[n] = g[n - 1]
    latest = max(latest, tg[n - 1])
    gates = gates + (n - 1)
    return s, latest, gates
}

def value_of(bits: Arr) -> Num {
    v = 0.0
    for i to len(bits) {
        v = v + bits[i] * pow(2.0, i)
    }
    return v
}

srand(SEED)
n_w: Int = len(WIDTHS)
depth_ripple = zeros(n_w)
depth_lookahead = zeros(n_w)
gates_ripple = zeros(n_w)
gates_lookahead = zeros(n_w)
wrong: Int = 0
checked: Int = 0
for w to n_w {
    width: Int = int(WIDTHS[w])
    for trial to N_RANDOM {
        xa = zeros(width)
        xb = zeros(width)
        for i to width {
            xa[i] = floor(2.0 * rand())
            xb[i] = floor(2.0 * rand())
        }
        if trial == 0 {
            #: the longest carry chain: all ones plus one
            for i to width {
                xa[i] = 1.0
                xb[i] = 0.0
            }
            xb[0] = 1.0
        }
        sr, dr, gr = ripple(xa, xb)
        sl, dl, gl = lookahead(xa, xb)
        depth_ripple[w] = max(depth_ripple[w], dr)
        depth_lookahead[w] = max(depth_lookahead[w], dl)
        gates_ripple[w] = float(gr)
        gates_lookahead[w] = float(gl)
        for i to width + 1 {
            if sr[i] != sl[i] {
                wrong = wrong + 1
            }
        }
        if width <= EXACT_WIDTH and value_of(sr) != value_of(xa) + value_of(xb) {
            wrong = wrong + 1
        }
        checked = checked + 1
    }
}
show depth_ripple
show depth_lookahead
show gates_ripple
show gates_lookahead
show wrong
show checked
gate_ratio_at_64 = gates_lookahead[n_w - 1] / gates_ripple[n_w - 1]
show gate_ratio_at_64

#: the figure: critical path against width for both adders
figure("Critical path of an n-bit adder", "bits n", "gate delays")
plot(WIDTHS * 1.0, depth_ripple * 1.0, "ripple carry, 2n + 4")
style("ripple carry, 2n + 4", "s2 circle")
plot(WIDTHS * 1.0, depth_lookahead * 1.0, "Kogge-Stone, 2 log2 n + 1")
style("Kogge-Stone, 2 log2 n + 1", "s1 square")

test "ripple carry: critical path 2n + 4 gate delays and 9n gates" {
    for w to n_w {
        assert_near(depth_ripple[w], 2.0 * WIDTHS[w] + 4.0, 0.0)
        assert_near(gates_ripple[w], 9.0 * WIDTHS[w], 0.0)
    }
}
test "Kogge-Stone: critical path 2 log2(n) + 1 gate delays" {
    for w to n_w {
        assert_near(depth_lookahead[w], 2.0 * round(log(WIDTHS[w]) / log(2.0)) + 1.0, 0.0)
    }
}
test "at 64 bits the lookahead adder uses about twice the gates" {
    assert_gt(gate_ratio_at_64, 1.9)
    assert_lt(gate_ratio_at_64, 2.1)
}
test "both adders are right on all 10,000 additions" {
    assert_true(wrong == 0)
    assert_true(checked == 10000)
}

#: pi
PI_K = 4.0 * atan(1.0)
SIZES = [32, 64, 128, 256]
#: the grid points this claim is about: at least FAR from either jump
FAR = PI_K / 4.0
#: the size the "below 3e-4" bound is stated at
AT_N = 128

#| sin x, plus 1 on [0, pi): jumps of +1 at x = 0 and -1 at x = pi.
def f(x: Num) -> Num {
    step = 0.0
    if x < PI_K {
        step = 1.0
    }
    return sin(x) + step
}

#| Distance from x in [0, 2 pi) to the nearer jump.
def jump_distance(x: Num) -> Num {
    return min(abs(x - PI_K), min(x, 2.0 * PI_K - x))
}

#| The largest error of the spectral derivative on n points, over the points at least FAR from a jump.
def spectral_far_error(n: Int) -> Num {
    h = 2.0 * PI_K / n
    re = zeros(n)
    im = zeros(n)
    for k to n {
        for j to n {
            re[k] = re[k] + f(j * h) * cos(k * j * h)
            im[k] = im[k] - f(j * h) * sin(k * j * h)
        }
    }
    worst = 0.0
    for j to n {
        if jump_distance(j * h) >= FAR {
            d = 0.0
            for k to n {
                #: the wavenumber of mode k: k below n / 2, k - n above, the Nyquist mode dropped
                w = 0.0
                if 2 * k < n {
                    w = k * 1.0
                }
                if 2 * k > n {
                    w = k - n * 1.0
                }
                c = cos(k * j * h)
                s = sin(k * j * h)
                d = d + w * (-im[k] * c - re[k] * s)
            }
            worst = max(worst, abs(d / n - cos(j * h)))
        }
    }
    return worst
}

#| The largest error of (f(x + h) - f(x - h)) / (2 h) on n points, over the same points.
def fd_far_error(n: Int) -> Num {
    h = 2.0 * PI_K / n
    worst = 0.0
    for j to n {
        if jump_distance(j * h) >= FAR {
            worst = max(worst, abs((f((j + 1) * h) - f((j - 1) * h)) / (2.0 * h) - cos(j * h)))
        }
    }
    return worst
}

n_sizes: Int = len(SIZES)
err_spectral = zeros(n_sizes)
err_fd = zeros(n_sizes)
fd_at_n = 0.0
for k to n_sizes {
    err_spectral[k] = spectral_far_error(int(SIZES[k]))
    err_fd[k] = fd_far_error(int(SIZES[k]))
    if int(SIZES[k]) == AT_N {
        fd_at_n = err_fd[k]
    }
}
show err_spectral
show err_fd
show fd_at_n
spectral_smallest = min(err_spectral)
show spectral_smallest

#: the figure: both errors at the points away from the jumps, against N
figure("Derivative error away from a jump", "grid points N", "largest error at least pi/4 from a jump")
xscale("log")
yscale("log")
plot(SIZES * 1.0, err_fd, "central difference")
style("central difference", "s1 circle")
plot(SIZES * 1.0, err_spectral, "spectral (Fourier)")
style("spectral (Fourier)", "s2 square")

test "away from the jumps the central difference's error falls by 3.9 to 4.1 per doubling" {
    for k to n_sizes - 1 {
        assert_gt(err_fd[k] / err_fd[k + 1], 3.9)
        assert_lt(err_fd[k] / err_fd[k + 1], 4.1)
    }
}
test "and is below 3e-4 at N = 128" {
    assert_lt(fd_at_n, 3.0e-4)
}
test "the spectral derivative's error at the same points stays above 0.7 for every N" {
    assert_gt(spectral_smallest, 0.7)
}

from ode.lu import lu_factor, lu_solve

N_FIRST: Int = 4
N_LAST: Int = 12

#| The n x n Hilbert matrix, H[i, j] = 1 / (i + j + 1).
def hilbert(n: Int) -> Arr {
    h = zeros(n, n)
    for i to n {
        for j to n {
            h[i, j] = 1.0 / (i + j + 1.0)
        }
    }
    return h
}

#| The binomial coefficient C(n, k) as a double (exact below 2^53).
def binom(n: Num, k: Num) -> Num {
    r = 1.0
    for i to int(k) {
        r = r * (n - i) / (i + 1.0)
    }
    return round(r)
}

#| The exact inverse of the n x n Hilbert matrix (its entries are integers).
def hilbert_inverse(n: Int) -> Arr {
    g = zeros(n, n)
    for i to n {
        for j to n {
            sgn = 1.0
            if (i + j) % 2 == 1 {
                sgn = -1.0
            }
            g[i, j] = sgn * (i + j + 1.0) * binom(n + i, n - j - 1.0) * binom(n + j, n - i - 1.0) * binom(i + j, i) * binom(i + j, i)
        }
    }
    return g
}

#| The infinity norm: the largest row sum of |a|.
def norm_inf(a: Arr) -> Num {
    n: Int = int(shape(a)[0])
    best = 0.0
    for i to n {
        s = 0.0
        for j to n {
            s = s + abs(a[i, j])
        }
        best = max(best, s)
    }
    return best
}

n_sizes: Int = N_LAST - N_FIRST + 1
log10_cond = zeros(n_sizes)
digits_correct = zeros(n_sizes)
for k to n_sizes {
    n: Int = N_FIRST + k
    h = hilbert(n)
    b = zeros(n)
    for i to n {
        for j to n {
            b[i] = b[i] + h[i, j]
        }
    }
    log10_cond[k] = log(norm_inf(h) * norm_inf(hilbert_inverse(n))) / log(10.0)
    piv = int_zeros(n)
    lu = copy(h)
    ok = lu_factor(lu, piv)
    x = lu_solve(lu, piv, b)
    err = 0.0
    for i to n {
        err = max(err, abs(x[i] - 1.0))
    }
    digits_correct[k] = min(16.0, -log(max(err, 1.0e-17)) / log(10.0))
}
show log10_cond
show digits_correct
cond_at_12 = log10_cond[n_sizes - 1]
digits_at_12 = digits_correct[n_sizes - 1]
show cond_at_12
show digits_at_12

#: the figure: correct digits against log10 of the condition number, with 16 - log10 kappa
DOUBLE_DIGITS = 16.0
fg_x = [log10_cond[0], log10_cond[n_sizes - 1]]
figure("Correct digits of the Hilbert solve, n = 4 to 12", "log10 of the condition number", "correct digits of x")
plot(fg_x, DOUBLE_DIGITS - fg_x, "16 - log10 kappa")
style("16 - log10 kappa", "dash s6 nomarker thin")
plot(log10_cond, digits_correct, "LU with partial pivoting")
style("LU with partial pivoting", "s1 circle")

test "the correct digits are between 1 below and 3 above 16 - log10 cond for n = 4 to 12" {
    for k to n_sizes {
        assert_gt(digits_correct[k] - (16.0 - log10_cond[k]), -1.0)
        assert_lt(digits_correct[k] - (16.0 - log10_cond[k]), 3.0)
    }
}
test "at n = 12 cond(H) is above 1e16 and fewer than 3 digits remain" {
    assert_gt(cond_at_12, 16.0)
    assert_lt(digits_at_12, 3.0)
}

SQRT2 = 1.4142135623730951
MAX_STEPS: Int = 8
#: the theory's constant f''(r) / (2 f'(r)) = 1 / (2 sqrt 2)
NEWTON_CONST = 1.0 / (2.0 * SQRT2)

errs = zeros(MAX_STEPS + 1)
x = 1.0
errs[0] = abs(x - SQRT2)
steps_to_exact: Int = -1
for k to MAX_STEPS {
    x = x - (x * x - 2.0) / (2.0 * x)
    errs[k + 1] = abs(x - SQRT2)
    if steps_to_exact < 0 and errs[k + 1] <= 2.3e-16 {
        steps_to_exact = k + 1
    }
}
show errs
show steps_to_exact
ratio = 0.0
for k to MAX_STEPS {
    if ratio == 0.0 and errs[k] < 1.0e-2 and errs[k + 1] > 1.0e-9 {
        ratio = errs[k + 1] / (errs[k] * errs[k])
    }
}
show ratio

#: bisection on [1, 2]: steps until the bracket is below the spacing of doubles near sqrt 2
lo = 1.0
hi = 2.0
bisection_steps: Int = 0
while hi - lo > 2.3e-16 {
    mid = 0.5 * (lo + hi)
    if mid * mid > 2.0 {
        hi = mid
    }
    else {
        lo = mid
    }
    bisection_steps = bisection_steps + 1
}
digits_per_bisection = log(2.0) / log(10.0)
show bisection_steps
show digits_per_bisection

#: the figure: the error of each Newton step, beside the bracket width of bisection
fg_newton_k = zeros(MAX_STEPS + 1)
for fg_k to MAX_STEPS + 1 {
    fg_newton_k[fg_k] = fg_k * 1.0
}
fg_bis_k = zeros(bisection_steps + 1)
fg_bis_w = zeros(bisection_steps + 1)
for fg_k to bisection_steps + 1 {
    fg_bis_k[fg_k] = fg_k * 1.0
    fg_bis_w[fg_k] = pow(0.5, fg_k * 1.0)
}
figure("Newton's method and bisection for sqrt(2)", "step", "error")
yscale("log")
plot(fg_bis_k, fg_bis_w, "bisection bracket")
style("bisection bracket", "s2 nomarker")
plot(fg_newton_k, errs, "Newton from x0 = 1")
style("Newton from x0 = 1", "s1 circle")

test "full double precision in 5 steps" {
    assert_true(steps_to_exact == 5)
}
test "bisection on [1, 2] needs 52 steps" {
    assert_true(bisection_steps == 52)
}
test "the error ratio e_(k+1) / e_k^2 is within 10% of 0.354" {
    assert_near(ratio / NEWTON_CONST, 1.0, 0.1)
    assert_near(NEWTON_CONST, 0.354, 0.0005)
}

N_POINTS: Int = 7

#| 1 - cos x by its Taylor series to the x^10 term, for |x| at most 0.1.
def one_minus_cos_series(x: Num) -> Num {
    x2 = x * x
    return x2 / 2.0 - x2 * x2 / 24.0 + x2 * x2 * x2 / 720.0 - x2 * x2 * x2 * x2 / 40320.0 + x2 * x2 * x2 * x2 * x2 / 3628800.0
}

#| -log10 of the relative error of v against the true value t, capped at 17.
def digits(v: Num, t: Num) -> Num {
    e = abs(v - t) / abs(t)
    if e == 0.0 {
        return 17.0
    }
    return min(17.0, -log(e) / log(10.0))
}

digits_direct = zeros(N_POINTS)
digits_half_angle = zeros(N_POINTS)
digits_expected_loss = zeros(N_POINTS)
for k to N_POINTS {
    x = pow(10.0, -(k + 1.0))
    t = one_minus_cos_series(x)
    s = sin(x / 2.0)
    digits_direct[k] = digits(1.0 - cos(x), t)
    digits_half_angle[k] = digits(2.0 * s * s, t)
    digits_expected_loss[k] = log(2.0 / (x * x)) / log(10.0)
}
show digits_direct
show digits_half_angle
#: x = 1e-4 is index 3, x = 1e-7 index 6
lost_at_1e4 = 16.0 - digits_direct[3]
show lost_at_1e4

#: the figure: correct digits of both forms against x
fg_x = zeros(N_POINTS)
for fg_k to N_POINTS {
    fg_x[fg_k] = pow(10.0, -(fg_k + 1.0))
}
figure("Correct digits of 1 - cos x", "x", "correct digits")
xscale("log")
plot(fg_x, digits_half_angle, "2 sin^2(x/2)")
style("2 sin^2(x/2)", "s1 circle")
plot(fg_x, digits_direct, "1 - cos x")
style("1 - cos x", "s2 square")

test "at x = 1e-4 the direct form has lost at least 7 digits" {
    assert_gt(lost_at_1e4, 7.0)
}
test "at x = 1e-7 fewer than 4 digits remain" {
    assert_lt(digits_direct[6], 4.0)
}
test "the direct form never keeps more than 2 digits above 16 - log10(2 / x^2)" {
    for k to N_POINTS {
        assert_lt(digits_direct[k], 16.0 + 2.0 - digits_expected_loss[k])
    }
}
test "2 sin^2(x / 2) keeps at least 15 digits from x = 1e-1 to 1e-7" {
    for k to N_POINTS {
        assert_gt(digits_half_angle[k], 15.0)
    }
}

